import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const RateUser = () => {
  const [usersToRate, setUsersToRate] = useState([]);
  const [error, setError] = useState("");

  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (!userId) return;

    fetch(`${API_BASE_URL}/api/ratings/partners/${userId}`)
      .then((res) => res.json())
      .then((data) => {
        if (Array.isArray(data)) {
          setUsersToRate(data);
        } else {
          setError("Invalid data format received");
          console.error("Expected array but got:", data);
        }
      })
      .catch((err) => {
        setError("Failed to load users.");
        console.error("Error fetching users to rate:", err);
      });
  }, [userId]);

  const handleRate = async (ratedUserId, rating) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          rater_id: userId,
          rated_id: ratedUserId,
          rating: rating,
        }),
      });

      if (res.ok) {
        alert("Rating submitted!");
        setUsersToRate((prev) => prev.filter((u) => u.id !== ratedUserId)); // remove from list
      } else {
        alert("Failed to submit rating.");
      }
    } catch (err) {
      console.error("Rating error:", err);
      alert("Something went wrong.");
    }
  };

  return (
    <div className="rate-page-wrapper">
      <Navbar />
      <main className="rate-user-wrapper">
        <h2>Rate Other Users</h2>
        {error && <p className="error-message">{error}</p>}
        {usersToRate.length === 0 ? (
          <p>No users to rate yet.</p>
        ) : (
          <div className="rate-user-grid">
            {usersToRate.map((user) => (
              <div className="rate-card" key={user.id}>
                <h4>{user.username}</h4>
                <p>Email: {user.email}</p>
                <p>
                  <strong>Average Rating:</strong>{" "}
                  {user.average_rating !== null ? `${user.average_rating} ⭐` : "Not rated yet"}
                </p>
                <div className="rating-buttons">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <button key={n} onClick={() => handleRate(user.id, n)}>
                      {n}⭐
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default RateUser;
